import React, { useState, useEffect } from 'react';
import { motion } from 'framer-motion';
import { Github, FolderGit2, GitBranch, Server, Activity, Users, Globe, Play, Lock, Terminal, Box, BoxSelect, ServerCog, Cpu, HardDrive, RefreshCw } from 'lucide-react';
import { toast } from 'sonner';

export default function GitHubEcosystemVault() {
  const [loading, setLoading] = useState(true);
  const [data, setData] = useState({
    totalProfiles: 17,
    totalRepos: 225,
    completed: 13,
    activeProfile: 'nklnchv-glitch',
    activeRepo: 'Microinvest-pro/openbalancer2',
    status: 'Running',
    lastUpdated: new Date().toLocaleTimeString(),
    profiles: [
      { name: 'nklnchv-glitch', repoCount: 4, status: 'Synced', icon: Globe },
      { name: 'krasavetsa7-cloud', repoCount: 12, status: 'Synced', icon: Users },
      { name: 'damqnhristov335-sudo', repoCount: 8, status: 'Synced', icon: Server },
      { name: 'Microinvest-pro', repoCount: 42, status: 'Syncing', icon: ServerCog },
    ],
    dockerServices: [
      { name: 'n8n-ob', type: 'Workflow', port: '5679->5678', status: 'Healthy', core: true },
      { name: 'supabase-db', type: 'Database', port: '5432', status: 'Healthy', core: true },
      { name: 'infisical-standalone', type: 'Vault', port: '8080', status: 'Healthy', core: true },
      { name: 'firecrawl-api', type: 'Crawler', port: '3002', status: 'Healthy', core: false },
      { name: 'supabase-kong', type: 'API Gateway', port: '8002', status: 'Healthy', core: true },
      { name: 'n8n-ob-tunnel', type: 'Network', port: '-', status: 'Healthy', core: true },
      { name: 'novnc-proxy', type: 'VNC', port: '8006', status: 'Healthy', core: false },
      { name: 'supabase-auth', type: 'Auth', port: '-', status: 'Healthy', core: true },
    ]
  });

  useEffect(() => {
    // Simulate real-time progress update from macmini-secondary MIGRATION_PROGRESS.json
    const interval = setInterval(() => {
      setData(prev => ({
        ...prev,
        completed: Math.min(prev.completed + 1, prev.totalRepos),
        lastUpdated: new Date().toLocaleTimeString(),
      }));
    }, 15000);
    
    setTimeout(() => setLoading(false), 800);
    return () => clearInterval(interval);
  }, []);

  const refreshStatus = () => {
    setLoading(true);
    setTimeout(() => {
      setLoading(false);
      toast.success('Successfully synced with Leon2 Migration Engine');
    }, 600);
  };

  return (
    <div className="space-y-6">
      {/* Top Banner */}
      <div className="bg-dark-800/80 backdrop-blur-md p-6 rounded-2xl border border-dark-700 shadow-xl flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div className="flex items-center space-x-4">
          <div className="p-3 bg-gradient-to-tr from-purple-500/20 to-pink-500/20 border border-purple-500/30 rounded-xl">
            <Github className="w-8 h-8 text-purple-400" />
          </div>
          <div>
            <h1 className="text-2xl font-bold text-white tracking-wide flex items-center gap-3">
              Ecosystem Deep Vault
              <span className="px-2 py-1 text-[10px] font-bold rounded-full bg-emerald-500/10 text-emerald-400 border border-emerald-500/20 uppercase">
                Live Migration
              </span>
            </h1>
            <p className="text-gray-400 text-sm mt-1 flex items-center gap-2">
              <HardDrive className="w-4 h-4 text-gray-500" />
              Target: /Volumes/PHILIPS_SSD/GitHub_Deep_Vault/ on macmini-secondary
            </p>
          </div>
        </div>
        <button 
          onClick={refreshStatus}
          disabled={loading}
          className="px-4 py-2 bg-dark-700 hover:bg-dark-600 rounded-xl text-sm font-semibold flex items-center gap-2 transition border border-dark-600"
        >
          <RefreshCw className={`w-4 h-4 ${loading ? 'animate-spin' : ''}`} />
          Sync State
        </button>
      </div>

      {/* Migration Progress Stats */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
        <div className="bg-dark-800/60 p-5 rounded-2xl border border-dark-700/50 flex flex-col">
          <span className="text-xs uppercase text-gray-400 font-bold tracking-wider">Total Repositories</span>
          <span className="text-3xl font-extrabold text-white mt-2">{data.totalRepos}</span>
          <div className="w-full h-1.5 bg-dark-700 rounded-full mt-auto mb-1">
            <div className="h-full bg-purple-500 rounded-full" style={{ width: `${(data.completed / data.totalRepos) * 100}%` }}></div>
          </div>
          <span className="text-[10px] text-gray-500 text-right">{data.completed} Downloaded</span>
        </div>
        <div className="bg-dark-800/60 p-5 rounded-2xl border border-dark-700/50 flex flex-col">
          <span className="text-xs uppercase text-gray-400 font-bold tracking-wider">GitHub Profiles</span>
          <span className="text-3xl font-extrabold text-white mt-2">{data.totalProfiles}</span>
          <span className="text-xs text-gray-400 mt-auto flex items-center gap-1">
            <Lock className="w-3.5 h-3.5 text-emerald-400" /> Authorized via Infisical
          </span>
        </div>
        <div className="bg-dark-800/60 p-5 rounded-2xl border border-purple-500/20 shadow-lg shadow-purple-500/5 flex flex-col lg:col-span-2">
          <span className="text-xs uppercase text-purple-400 font-bold tracking-wider flex items-center gap-2">
            <Terminal className="w-4 h-4" /> Current Operation
          </span>
          <div className="mt-2 text-sm text-gray-300 font-mono bg-dark-900/50 p-3 rounded-lg border border-dark-700/50">
            <div className="text-emerald-400">&gt; Mining PRs, Commits, and Issues for:</div>
            <div className="text-white font-bold mt-1">{data.activeRepo}</div>
            <div className="text-xs text-gray-500 mt-2">Active Profile: {data.activeProfile}</div>
          </div>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        {/* Discovered Ecosystems */}
        <div className="bg-dark-800/80 p-6 rounded-2xl border border-dark-700 shadow-xl">
          <h2 className="text-lg font-bold text-white mb-4 flex items-center gap-2">
            <FolderGit2 className="w-5 h-5 text-cyan-400" /> Discovered Ecosystems
          </h2>
          <div className="space-y-3">
            {data.profiles.map((profile, i) => (
              <div key={i} className="flex items-center justify-between p-3 bg-dark-900/60 rounded-xl border border-dark-700/40 hover:border-cyan-500/30 transition">
                <div className="flex items-center gap-3">
                  <div className="p-2 bg-dark-800 rounded-lg text-gray-400">
                    <profile.icon className="w-4 h-4" />
                  </div>
                  <div>
                    <div className="text-sm font-bold text-gray-200">{profile.name}</div>
                    <div className="text-[10px] text-gray-500">{profile.repoCount} repositories</div>
                  </div>
                </div>
                <div className={`text-xs font-semibold px-2.5 py-1 rounded-full ${
                  profile.status === 'Synced' ? 'bg-emerald-500/10 text-emerald-400 border border-emerald-500/20' : 'bg-cyan-500/10 text-cyan-400 border border-cyan-500/20 animate-pulse'
                }`}>
                  {profile.status}
                </div>
              </div>
            ))}
          </div>
        </div>

        {/* Integrated Core Docker Services */}
        <div className="bg-dark-800/80 p-6 rounded-2xl border border-dark-700 shadow-xl">
          <h2 className="text-lg font-bold text-white mb-4 flex items-center gap-2">
            <BoxSelect className="w-5 h-5 text-amber-400" /> Integrated Fleet Services
          </h2>
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
            {data.dockerServices.map((service, i) => (
              <div key={i} className="p-3 bg-dark-900/60 rounded-xl border border-dark-700/40 hover:border-amber-500/30 transition flex flex-col justify-between h-24">
                <div className="flex items-center justify-between">
                  <div className="text-sm font-bold text-gray-200 truncate">{service.name}</div>
                  {service.core && <span className="w-2 h-2 rounded-full bg-amber-400"></span>}
                </div>
                <div>
                  <div className="text-[10px] text-gray-400 uppercase tracking-wide">{service.type}</div>
                  <div className="text-xs text-gray-500 font-mono mt-1">Port: {service.port}</div>
                </div>
              </div>
            ))}
          </div>
        </div>
      </div>
    </div>
  );
}
